mapper.select:
SELECT FROM TB_REL_VRSN V JOIN TB_PROM PR ON PR.IPROM_NO = V.IPROM_NO JOIN ( SELECT MAX(PR2.ILAW_NO) AS LAW_NO, V2.ICTNS_ID FROM TB_REL_VRSN V2 JOIN TB_PROM PR2 ON PR2.IPROM_NO = V2.IPROM_NO WHERE PR2.ILAW_ID = #{lawId} AND PR2.ILAW_NO <= #{lawNo}
AND PR2.ILAW_NO >= #{notDiffLawNo}
AND ( V2.SFLAG IS NULL OR V2.SFLAG = 'PROMULGATION' ) GROUP BY V2.ICTNS_ID ) MX ON MX.ICTNS_ID = V.ICTNS_ID AND PR.ILAW_NO = MX.LAW_NO LEFT OUTER JOIN TB_REL_VRSN_CATE C ON V.IRVCATE_NO = C.IRVCATE_NO WHERE PR.ILAW_ID = #{lawId} AND ( V.SFLAG IS NULL OR V.SFLAG = 'PROMULGATION' ) AND ( ( PR.ILAW_NO = #{lawNo} AND NVL(V.SVRSN_YN, 'N') = 'N' ) OR V.SVRSN_YN = 'Y' ) AND ( V.STABLE NOT IN ('TB_REL_LNK', 'TB_REL_DMN_LNK') OR PR.ILAW_NO = #{lawNo} OR NOT EXISTS ( SELECT 1 FROM TB_REL_VRSN VC JOIN TB_PROM PC ON PC.IPROM_NO = VC.IPROM_NO WHERE PC.ILAW_ID = #{lawId} AND PC.ILAW_NO = #{lawNo} AND VC.STABLE = V.STABLE AND ( VC.SFLAG IS NULL OR VC.SFLAG = 'PROMULGATION' ) ) ) ORDER BY NVL(C.ISEQ, 9999), C.STITLE, NVL(V.ISEQ, 9999), V.IRVRSN_NO

SELECT 
  FROM TB_REL_VRSN V
  LEFT OUTER JOIN TB_REL_VRSN_CATE C ON V.IRVCATE_NO = C.IRVCATE_NO
 WHERE V.IPROM_NO = #{promNo}
   AND V.STABLE   = #{stable}
   AND V.SFLAG    = #{flag}


   AND V.SFULL_ITEM = #{fullItem}


   AND ( V.SFULL_ITEM IS NULL OR V.SFULL_ITEM = '' OR V.SFULL_ITEM = '0' )


 ORDER BY V.IRVRSN_NO DESC
 LIMIT 1

mapper.update:
UPDATE TB_REL_VRSN
   SET SFULL_ITEM = #{newFullItem}
 WHERE IPROM_NO   = #{promNo}
   AND SFLAG      = #{flag}
   AND SFULL_ITEM = #{oldFullItem}

