SELECT NVL(MAX(ISEQ), 0) + 1
  FROM TB_REL_VRSN
 WHERE IPROM_NO = #{promNo}


   AND IRVCATE_NO = #{cateNo}


   AND ( IRVCATE_NO IS NULL OR IRVCATE_NO = 0 )
